entries[439890] = { ["name"] = "Strategische Infusion", ["text"] = "Wildheit\n'Tigerfuror' und der Angriff aus 'Schleichen' heraus erhöht die Chance für 'Schreddern', 'Krallenhieb' und 'Prankenhieb' kritisch zu treffen 6 Sek. lang um 8%.\n\nDas Wirken von 'Nachwachsen' erhöht die Chance, dass Eure regelmäßigen Heileffekte kritisch heilen 10 Sek. lang um 8%.\n\nWiederherstellung\nDer Angriff aus 'Schleichen' heraus erhöht die Chance für 'Schreddern', 'Krallenhieb' und 'Prankenhieb' kritisch zu treffen 6 Sek. lang um 8%.\n\nDas Wirken von 'Nachwachsen' erhöht die Chance, dass Eure regelmäßigen Heileffekte kritisch heilen 10 Sek. lang um 8%." }
