entries[439988] = { ["name"] = "Sprudelndes Starkbier", ["text"] = "300 Meter Reichweite\nSofort\nI'pa stößt Met aus und fügt allen Spielcharakteren 8 Sek. lang alle 2 Sek. 1939560 Feuerschaden zu. Mettröpfchen schleudern nach außen und fügen Spielcharakteren im Umkreis von 3 Metern 7273348 zusätzlichen Feuerschaden zu.\n\nAus einigen Tröpfchen bilden sich Bräutropfen." }
entries[439989] = { ["name"] = "Synergistischer Schritt", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Nx und Vx 100 Energie erreicht haben, rasen sie immer wieder durch die Arena und fügen Spielercharakteren auf ihrem Weg 1939560 körperlichen Schaden zu. Dann wechseln sie zwischen der angreifenden und der unterstützenden Rolle hin und her." }
entries[439990] = { ["name"] = "Netzbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nTakazj verschießt klebrige Gespinstknoten in der Kammer, die die Bewegungsgeschwindigkeit von Spielercharakteren um 20% verringern und ihnen alle 1 Sek. 345379 körperlichen Schaden zufügen, während diese sich im Effektbereich befinden.\n\nDer Knoten in der Mitte bricht bei Berührung aus, was Spielercharakteren innerhalb von 10 Metern 1732248 Naturschaden zufügt und ' Bindende Netze ' einsetzt, um zwei Spielercharaktere mit aneinanderzubinden.\n\nWenn Anub'arash durch Stränge von 'Bindende Netze' stürmt, wird er 'Umschlungen'." }
