entries[440040] = { ["name"] = "Xalans Grausamkeit", ["text"] = "Gebrechen\nDurch Eure Zauber und Fähigkeiten verursachter Schattenschaden wird um 6% erhöht und die kritische Trefferchance Eurer Schattenzauber aus allen Quellen steigt um 10%.\n\nZerstörung\nDurch Eure Zauber und Fähigkeiten verursachter Schattenschaden wird um 8% erhöht und die kritische Trefferchance Eurer Schattenzauber aus allen Quellen steigt um 10%." }
entries[440041] = { ["name"] = "Klettern" }
entries[440042] = { ["name"] = "Verdunkelnde Seele", ["text"] = "Dämonologie, Zerstörung\nDer durch 'Feuerbrand' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\nSchaden durch 'Chaosblitz' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort. Schaden, der durch 'Feuerregen' verursacht wird, verbraucht 1 Sek. von 'Verdunkelnde Seele'.\n\nGebrechen\nDer durch 'Verderbnis' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\nSchaden durch 'Unheilvolle Euphorie' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort." }
entries[440043] = { ["name"] = "Geschwärzte Seele", ["text"] = "Das Verbrauchen von Seelensplittern für Schadenszauber verderbt Gegner, die von Eurem 'Welken' betroffen sind, noch weiter und erhöht die Anzahl der Stapel von 'Welken' um 1.\n\nImmer wenn sich die Stapel von 'Welken' erhöhen, besteht eine Chance, dass der Effekt zerfällt, wodurch alle 1 Sek. ein Stapel entfernt wird, um dem Opfer (76.6411% der Zaubermacht) Schattenflammenschaden zuzufügen, bis noch 1 Stapel übrig ist." }
entries[440044] = { ["name"] = "Xalans Wildheit", ["text"] = "Gebrechen\nDurch Eure Zauber und Fähigkeiten verursachter Feuerschaden wird um 6% erhöht und die kritische Trefferchance Eurer Feuerzauber aus allen Quellen steigt um 10%.\n\nZerstörung\nDurch Eure Zauber und Fähigkeiten verursachter Feuerschaden wird um 8% erhöht und die kritische Trefferchance Eurer Feuerzauber aus allen Quellen steigt um 10%." }
entries[440045] = { ["name"] = "Mal von Peroth'arn", ["text"] = "Zerstörung\nErhöht den kritischen Schaden von 'Welken' um 10%.\n\n'Welken' hat eine Chance, bei kritischen Treffern einen Stapel zu erhalten. Auf diese Weise erhaltene Stapel aktivieren 'Geschwärzte Seele' nicht.\n\nGebrechen\nErhöht den kritischen Schaden von 'Welken' um 25%.\n\n'Welken' hat eine Chance, bei kritischen Treffern einen Stapel zu erhalten. Auf diese Weise erhaltene Stapel aktivieren 'Geschwärzte Seele' nicht." }
entries[440046] = { ["name"] = "Mal von Xavius", ["text"] = "[ Agonie : Erhöht den Schaden von 'Agonie' um 20% / Erhöht den Schaden von 'Welken' um 25%.]\n'Geschwärzte Seele' verursacht pro Stapel von 'Welken' 2% mehr Schaden." }
entries[440047] = { ["name"] = "Wöchentlich erweckte Aktivitäten", ["text"] = "Sofort\nBeim Abschluss dieser Quest könnt Ihr wöchentlich einen Funken für das Handwerk erhalten.\n\nIhr habt Euren wöchentlichen Funken für das Handwerk diese Woche schon erhalten" }
entries[440048] = { ["name"] = "Zornsäerrituale", ["text"] = "'Welken' verursacht 30% erhöhten regelmäßigen Schaden, aber die Dauer ist um 15% verkürzt." }
entries[440049] = { ["name"] = "Synergistischer Schritt", ["text"] = "100 Meter Reichweite\nSofort\nWenn Nx und Vx 100 Energie erreicht haben, rasen sie immer wieder durch die Arena und fügen Spielercharakteren auf ihrem Weg 1939560 körperlichen Schaden zu. Dann wechseln sie zwischen der angreifenden und der unterstützenden Rolle hin und her." }
entries[440051] = { ["name"] = "Herzschindertaktiken", ["text"] = "Der Schaden von 'Welken' wird um 20% erhöht. Wenn die Stapel von 'Welken' durch 'Geschwärzte Seele' erhöht werden, besteht eine Chance, einen zusätzlichen Stapel zu erhalten." }
entries[440055] = { ["name"] = "Die Saat ihres Untergangs", ["text"] = "Gebrechen\nWenn 'Welken' 8 Stapel oder das Opfer 20% Gesundheit erreicht, fügt 'Welken' dem Opfer alle 1 Sek. (76.6411% der Zaubermacht) Schattenflammenschaden zu, bis 1 Stapel übrig bleibt.\n\nWenn 'Geschwärzte Seele' Schaden verursacht, besteht eine Chance, dass Ihr 'Gequältes Crescendo' erhaltet.\n\nZerstörung\nWenn 'Welken' 8 Stapel oder das Opfer 20% Gesundheit erreicht, fügt 'Welken' dem Opfer alle 1 Sek. (76.6411% der Zaubermacht) Schattenflammenschaden zu, bis 1 Stapel übrig bleibt.\n\nWenn 'Geschwärzte Seele' Schaden verursacht, besteht eine Chance, dass Ihr 2 Stapel von 'Brennpunkt' erhaltet." }
entries[440056] = { ["name"] = "Bandagieren", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nHeilt ein Ziel um eine geringe Menge Gesundheit." }
entries[440057] = { ["name"] = "Fluch der Satyrn", ["text"] = "'Fluch der Schwäche' ist ermächtigt und verwandelt sich in 'Fluch der Satyrn'.\n\nFluch der Satyrn\nErhöht die Zeit zwischen Angriffen eines Gegners 2 Min. lang um 20% und die Zauberzeit aller Zauber um 30%.\n\nFlüche: Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
