entries[440116] = { ["name"] = "Harmonische Verfassung", ["text"] = "Wildheit\nDie Heilung durch 'Nachwachsen', die Ihr auf Euch selbst wirkt, ist um 25% erhöht.\n\nWiederherstellung\nDie Heilung durch 'Nachwachsen', die Ihr auf Euch selbst wirkt, ist um 35% erhöht." }
entries[440117] = { ["name"] = "Zwillingssprossen", ["text"] = "Wenn 'Blutsucherranken' oder 'Symbiotische Blüten' wachsen, haben sie eine Chance von 30%, ein Wachstum derselben Art auf einem gültigen Ziel in der Nähe hervorzurufen." }
entries[440118] = { ["name"] = "Einpflanzen", ["text"] = "Wiederherstellung\nDas Zaubern von 'Rasche Heilung' oder 'Wildes Wachstum' lässt 6 Sek. lang eine 'Symbiotische Blüte' auf dem Ziel wachsen.\n\nWildheit\nWenn Ihr 'Tigerfuror' erhaltet oder verliert, lässt Eure nächste Nahkampffähigkeit gegen ein Einzelziel 4 Sek. lang eine 'Blutsucherranke' auf dem Ziel wachsen.\n\n(200ms Abklingzeit)" }
entries[440119] = { ["name"] = "Kraftvolle Kriecher", ["text"] = "'Blutsucherranken' erhöhen den Schaden, den Eure Fähigkeiten betroffenen Gegnern zufügen, um 6%.\n\n'Symbiotische Blüte' erhöht die Heilung, die Eure Zauber betroffenen Zielen gewähren, um 20%." }
entries[440120] = { ["name"] = "Berstender Wuchs", ["text"] = "Wenn 'Blutsucherranken' ablaufen oder Ihr 'Wilder Biss' auf ihr Ziel anwendet, explodieren sie in einem Schwall aus Dornen, der Gegnern in der Nähe (120% der Angriffskraft) körperlichen Schaden zufügt. Ziele über 5 Ziele hinaus erleiden weniger Schaden.\n\nWenn 'Symbiotische Blüte' abläuft oder Ihr 'Verjüngung' gegen ihr Ziel einsetzt, wachsen Blumen um das Ziel herum, die das Ziel und bis zu 3 Verbündete in der Nähe um (34.5% der Zaubermacht) Gesundheit heilen." }
