entries[440178] = { ["name"] = "Tollkühner Einschlag", ["text"] = "Sofort\nAnub'arash stürmt nach vorne, fügt allen Spielercharakteren auf seinem Weg 7483210 Naturschaden zu und stößt sie weg.\n\nWenn er mit einer Wand kollidiert, entfesselt Anub'arash eine tödliche Schockwelle, die allen Spielercharakteren 17268945 Naturschaden zufügt." }
