entries[440185] = { ["name"] = "Infektiöse Sporen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde schleudert eine Spore auf sein aktuelles Ziel, fügt Spielercharakteren innerhalb von 3 Metern um den Einschlag Naturschaden und 3 Sek. lang alle 3 Sek. zusätzlichen Naturschaden zu." }
