entries[440362] = { ["name"] = "Positiv aufgeladen", ["text"] = "Sofort\nPositiv aufgeladen, was Euren verursachten Schaden um 3% erhöht, aber Euch alle 2 Sek. 1 Naturschaden zufügt. Bis zu 10-mal stapelbar.\n\nWenn ' Positiv aufgeladen ' bei mindestens 5 Stapeln entfernt wird, schlägt ein ' Elektrischer Schock ' auf die Gegner um Euch herum über." }
