entries[440365] = { ["name"] = "Verbesserte Sicht", ["text"] = "Sofort\nGewährt dem spezialisierten Sammler von sporenverschmolzenen Kräutern magisch verbesserte Sicht und ermöglicht es, getarnte Sammelvorkommen zu erkennen." }
