entries[440989] = { ["name"] = "Kolossale Macht", ["text"] = "Sofort\nSchutz\nEure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n'Schildschlag' gewährt einen Stapel von 'Kolossale Macht' und 'Rache' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft.\n\nWaffen\nEure 'Kolossale Macht' erhöht den verursachten Schaden Eures nächsten Einsatzes von 'Demolieren' um 10%. Bis zu 5-mal stapelbar.\n\n'Tödlicher Stoß' gewährt einen Stapel von 'Kolossale Macht' und 'Spalten' gewährt einen Stapel von 'Kolossale Macht', wenn die Fähigkeit 3 oder mehr Ziele trifft." }
