entries[441135] = { ["name"] = "Bienen!", ["text"] = "50 Meter Reichweite\nSofort 1 min Abklingzeit\nÄrgert alle Gegner innerhalb von 40 Metern um den Zielort, fordert sie zum Kampf heraus und belegt sie 30 Sek. lang mit 'Beulen'. Nur im Freien einsetzbar.\n\nBeulen :\nLässt einen Gegner 30 Sek. lang 5% mehr Schaden erleiden. Wenn der Gegner Schaden erleidet, besteht die Chance, dass ihm weitere Beulen zugefügt werden." }
