entries[441144] = { ["name"] = "Ungesehene Klinge", ["text"] = "100 Meter Reichweite\nSofort\nGesetzlosigkeit\n'Finsterer Stoß' und 'Hinterhalt' schlagen nun auch mit 'Ungesehene Klinge' zu, was (370% der Angriffskraft) Schaden verursacht. Getroffene Ziele sind 10 Sek. lang entmutigt.\n\nEntmutigte Ziele erleiden 5% mehr Schaden von Euch und können Eure Angriffe nicht parieren.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nTäuschung\nund 'Schattenschlag' schlagen nun auch mit 'Ungesehene Klinge' zu, was (370% der Angriffskraft) Schaden verursacht. Getroffene Ziele sind 10 Sek. lang entmutigt.\n\nEntmutigte Ziele erleiden 5% mehr Schaden von Euch und können Eure Angriffe nicht parieren.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten." }
entries[441145] = { ["name"] = "Vergifteter Impuls", ["text"] = "200 Meter Reichweite\nSofort\nNezarox stößt einen Giftimpuls aus, der 575632 Naturschaden verursacht und Spielercharaktere innerhalb von 100 Metern mit ' Haftendes Toxin ' belegt." }
entries[441146] = { ["name"] = "Ungesehene Klinge", ["text"] = "Gesetzlosigkeit\n'Finsterer Stoß' und 'Hinterhalt' schlagen nun auch mit 'Ungesehene Klinge' zu, was (370% der Angriffskraft) Schaden verursacht. Getroffene Ziele sind 10 Sek. lang entmutigt.\n\nEntmutigte Ziele erleiden 5% mehr Schaden von Euch und können Eure Angriffe nicht parieren.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nTäuschung\nund 'Schattenschlag' schlagen nun auch mit 'Ungesehene Klinge' zu, was (370% der Angriffskraft) Schaden verursacht. Getroffene Ziele sind 10 Sek. lang entmutigt.\n\nEntmutigte Ziele erleiden 5% mehr Schaden von Euch und können Eure Angriffe nicht parieren.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\n(750ms Abklingzeit)" }
