entries[441155] = { ["name"] = "Karnivorenkraftprobe", ["text"] = "50 Meter Reichweite\nSofort\nUlgrax speit Spinnweben auf einen Spielercharakter und alle Verbündeten im Umkreis von 10 Metern und verursacht 17331401 Naturschaden, die gleichmäßig auf alle Spielercharaktere aufgeteilt werden, und fesselt sie an Ulgrax.\n\nGefesselte Spielercharaktere erleiden alle 2 Sek. 575632 Naturschaden und werden zu Ulgrax gezogen. Die Stärke, mit der Ulgrax die Spielercharaktere anzieht, wird für jeden gefesselten Spielercharakter verringert." }
