entries[441246] = { ["name"] = "Unerbittliche Belagerung", ["text"] = "Verheerung\nFür jede Sekunde, die Ihr Euch im Kampf befindet, verursachen 'Azurstoß', 'Lebendige Flamme' und 'Desintegration' 1% mehr Schaden, bis zu einem Maximum von 15%.\n\nBewahrung, Verstärkung\nFür jede Sekunde, die Ihr Euch im Kampf befindet, verursachen 'Azurstoß', 'Lebendige Flamme' und 'Eruption' 1% mehr Schaden, bis zu einem Maximum von 15%." }
