entries[441285] = { ["name"] = "Dunkelparanoia", ["text"] = "100 Meter Reichweite\nSofort\nNx erhöht die Furcht eines zufälligen Spielercharakters und verursacht 12 Sek. lang alle 2 Sek. 7 Schattenschaden.\n\nUnter der Wirkung von ' Dunkelparanoia ' in der Nähe von Verbündeten zu stehen, verursacht 18 Schattenschaden und macht ihnen 5 Sek. lang Angst." }
