entries[441287] = { ["name"] = "Alarm schlagen", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 4 sek.)\nDer Zauberer schlägt Alarm und ruft 4 Sek. lang alle 2 Sek. nerubische Verstärkung herbei." }
