entries[441289] = { ["name"] = "Zähe Dunkelheit", ["text"] = "100 Meter Reichweite\nWirken in 3.5 sek.\nDas Koaglamat schmettert auf den Boden, stößt Spielercharaktere zurück und setzt in der Arena Kugeln aus geronnenem Schwarzblut aus Kanistern frei, die in seine Richtung fliegen.\n\nKugeln aus Schwarzblut, die das Koaglamat erreichen, werden absorbiert und stellen 7% seiner maximalen Gesundheit wieder her.\n\nSpielercharaktere, die Kugeln aus Schwarzblut berühren, absorbieren sie und werden mit ' Verderbter Überzug ' belegt. Das Absorbieren einer Kugel erzeugt an ihrer Position eine Lache aus Schwarzblut, die allen Spielercharakteren darin 1212225 Schattenschaden zufügt und ihre Bewegungsgeschwindigkeit um 35% verringert." }
entries[441290] = { ["name"] = "Sengende Flammen", ["text"] = "30 Meter Reichweite\nSofort\nWer in den Flammen steht, erleidet alle 1 Sek. 20 Feuerschaden." }
entries[441291] = { ["name"] = "Catalyzing Froth", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ein Spielercharakter den Schaum berührt, explodiert er und belegt den Spielercharakter mit ' Konzentriertes Toxin '.\n\nDiese Explosion schleudert den Spielercharakter 8 Meter in die Luft und fügt allen Spielercharakteren 1151263 Naturschaden zu und belegt sie mit ' Schäumendes Toxin ' und ' Toxische Reaktion '. Außerdem wird ein Giftklumpen weggeschleudert, der ' Giftige Wellen ' auslöst.\n\n' Toxinnova ' zerstreut explodierten Schaum zu einer Lache aus ' Säure '." }
