entries[441294] = { ["name"] = "Gezackter Stoß", ["text"] = "8 Meter Reichweite\nWirken in 1 sek.\nInflicts 1151263 Physical damage to an enemy every 1 sec for 8 Sek.." }
entries[441295] = { ["name"] = "Raureifdolch", ["text"] = "100 Meter Reichweite\nSofort\nVx versieht ihre Dolche mit Eis und stößt sie in ihr aktuelles Ziel, wodurch sie 7273348 körperlichen Schaden und 10 Anwendungen von ' Eisiges Blut ' verursacht. Dann zerspringen die Dolche und fügen allen Spielercharakteren 2424449 Frostschaden zu." }
entries[441296] = { ["name"] = "Spitzhacke gravieren", ["text"] = "Wirken in 3 sek.\nGraviert Eure Spitzhacke mit einer Rune, die es Euch gestattet, Runen aus chiffrierten Erzadern zu sammeln." }
entries[441298] = { ["name"] = "Eisiges Blut", ["text"] = "200 Meter Reichweite\nSofort\nDas Blut des Ziels beginnt zu gefrieren und fügt ihm alle 1 Sek. 727335 Frostschaden zu. Dieser Effekt ist stapelbar.\n\nWenn Ihr Euch in der Nähe eines anderen Spielercharakters aufhaltet, wird alle 1 Sek. pro Spielercharakter 1 Anwendung dieses Effekts entfernt." }
