entries[441316] = { ["name"] = "Rasende Sprünge", ["text"] = "Kanalisiert (Wirken in 6 sek.)\nDer Zaubernde springt 6 Sek. lang alle 1.5 Sek. auf einen Spielcharakter in der Nähe zu, verursacht 1439079 körperlichen Schaden und belegt Spielercharaktere im Umkreis von 4 Metern um jeden Einschlagsort mit ' Zerfetzte Wunde '." }
