entries[441321] = { ["name"] = "Makellose Gestalt", ["text"] = "Täuschung\n'Ungesehene Klinge' und 'Geheimtechnik' erhöhen den Schaden Eurer Finishing-Moves 12 Sek. lang um 3%.\n\nMehrere Anwendungen können einander überlappen.\n\nGesetzlosigkeit\n'Ungesehene Klinge' und 'Mordlust' erhöhen den Schaden Eurer Finishing-Moves 12 Sek. lang um 3%.\n\nMehrere Anwendungen können einander überlappen." }
entries[441324] = { ["name"] = "Unvergessener goldener Greif", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren unvergessenen goldenen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"In Sturmwind sind Löwen beliebt, und der Greif ist zur Hälfte Löwe. Deswegen sind diese Kreaturen ein wichtiger Bestandteil der Luftreisen durch die Gebiete der Allianz.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25" }
entries[441325] = { ["name"] = "Unvergessener Windreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren grünen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Hunderte Schlachten in Dutzenden Kampagnen wurden auf dem Rücken dieser geehrten Kreaturen bestritten und gewonnen.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25" }
entries[441326] = { ["name"] = "Makellose Gestalt", ["text"] = "Sofort\n'Ungesehene Klinge' und [ Gesetzlosigkeit : 'Mordlust' /\n\nTäuschung\n'Geheimtechnik' ] erhöhen den Schaden Eurer Finishing-Moves 12 Sek. lang um 3%.\n\nMehrere Anwendungen können einander überlappen." }
