entries[441381] = { ["name"] = "Synergistischer Schritt", ["text"] = "Wirken in 2.5 sek.\nWenn Nx und Vx 100 Energie erreicht haben, rasen sie immer wieder durch die Arena und fügen Spielercharakteren auf ihrem Weg 1939560 körperlichen Schaden zu. Dann wechseln sie zwischen der angreifenden und der unterstützenden Rolle hin und her." }
