entries[441387] = { ["name"] = "Kräfte sammeln", ["text"] = "Sofort\nWenn Eure Gesundheit unter 35% sinkt, erhaltet Ihr 'Kräfte sammeln', was Euch im Verlauf von 2 Sek. um 12% Eurer maximalen Gesundheit heilt.\n\nDieser Effekt kann nicht öfter als einmal alle 60 Sek. auftreten." }
